// Read content from source directory
// Customize SOURCE_DIR to your content location
const fs = require('fs');
const path = require('path');

const SOURCE_DIR = '/home/node/workflows/content-inbox';
const articles = [];

try {
  const files = fs.readdirSync(SOURCE_DIR).filter(f => f.endsWith('.md'));
  for (const file of files.slice(0, 50)) {
    const content = fs.readFileSync(path.join(SOURCE_DIR, file), 'utf8');
    const fmMatch = content.match(/^---\n([\s\S]*?)\n---/);
    let meta = {};
    if (fmMatch) {
      for (const line of fmMatch[1].split('\n')) {
        const [key, ...val] = line.split(':');
        if (key && val.length) meta[key.trim()] = val.join(':').trim();
      }
    }
    const body = content.replace(/^---[\s\S]*?---\n?/, '').trim();
    articles.push({ json: { file, title: meta.title || file, url: meta.url || '', tags: meta.tags || 'uncategorized', body: body.slice(0, 1000) } });
  }
} catch (e) {
  return [{ json: { error: `Could not read ${SOURCE_DIR}: ${e.message}` } }];
}

return articles;

// Group articles by tag/category
const items = $input.all();
const groups = {};

for (const item of items) {
  const tag = item.json.tags || 'uncategorized';
  if (!groups[tag]) groups[tag] = [];
  groups[tag].push(item.json);
}

return Object.entries(groups).map(([category, articles]) => ({
  json: { category, articles, count: articles.length }
}));

