// Compile all category digests into final HTML email body
const items = $input.all();
let html = '<h1>Weekly Content Digest</h1>';
html += `<p style="color:#666">${new Date().toLocaleDateString()}</p>`;

for (const item of items) {
  const text = item.json?.candidates?.[0]?.content?.parts?.[0]?.text || 'No digest generated';
  html += `<h2>${item.json.category || 'General'}</h2>`;
  html += `<div>${text.replace(/\n/g, '<br>')}</div><hr>`;
}

return [{ json: { subject: `Content Digest - ${new Date().toLocaleDateString()}`, html, to: $env.DIGEST_TO_EMAIL || 'you@example.com', from: $env.DIGEST_FROM_EMAIL || 'you@example.com' } }];
